(6785420, 1017886, 40391, '<td valign="top">A wonderful concept with the use of shallow DoF but the subject of focus just misses for me.</td>', 'A wonderful concept with the use of shallow DoF but the subject of focus just misses for me.', '2012-06-04 07:01:32.000000', NULL, 1),
(6785421, 1017941, 40391, '<td valign="top">A nice contrasting subject against the green background</td>', 'A nice contrasting subject against the green background', '2012-06-04 07:03:58.000000', NULL, 1),
(6785423, 1018176, 40391, '<td valign="top">Excellent capture of the bug and very green. A little more contrast would have been perfect</td>', 'Excellent capture of the bug and very green. A little more contrast would have been perfect', '2012-06-04 07:08:17.000000', NULL, 1),
(6785425, 1017993, 40391, '<td valign="top">Perfect colour, contrast and DoF.</td>', 'Perfect colour, contrast and DoF.', '2012-06-04 07:09:13.000000', NULL, 1),
